1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.time.temporal.ChronoUnit;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * Points added when the owner has an email address.
26	     */
27	    private static final int EMAIL_POINTS = 2;
28	
29	    /**
30	     * Points added when the owner has no namesakes ({@code namesakeCount} is 0).
31	     */
32	    private static final int NO_NAMESAKE_POINTS = 1;
33	
34	    /**
35	     * Points added when the owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members.
36	     */
37	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
38	
39	    /**
40	     * The household size (members, including the owner) at which the large-household points are awarded.
41	     */
42	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
43	
44	    /**
45	     * Points added when the owner's tenure exceeds {@value #TENURE_POINTS_DAYS} days.
46	     */
47	    private static final int TENURE_POINTS = 3;
48	
49	    /**
50	     * Tenure, in days, that an owner must exceed to earn the tenure points.
51	     */
52	    private static final int TENURE_POINTS_DAYS = 365;
53	
54	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
55	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
56	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
57	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
58	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
59	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
60	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
61	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity(), owner.getPostcode()))")
62	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
63	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
64	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
65	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
66	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
67	    public abstract OwnerDto toOwnerDto(Owner owner);
68	
69	    public abstract Owner toOwner(OwnerDto ownerDto);
70	
71	    @Mapping(target = "id", ignore = true)
72	    @Mapping(target = "pets", ignore = true)
73	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
74	
75	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
76	
77	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
78	
79	    /**
80	     * Computes an owner's membership points. Points start at 0 and accumulate: {@value #EMAIL_POINTS} when an
81	     * email is present, {@value #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
82	     * {@value #LARGE_HOUSEHOLD_POINTS} for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, and
83	     * {@value #TENURE_POINTS} for tenure of more than {@value #TENURE_POINTS_DAYS} days (measured from
84	     * {@code registrationDate}). Because a newly created owner has zero tenure, a new owner never earns the
85	     * tenure points.
86	     *
87	     * @param owner the owner whose points are being computed
88	     * @return the owner's membership points (0 or more)
89	     */
90	    protected Integer membershipPoints(Owner owner) {
91	        int points = 0;
92	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
93	            points += EMAIL_POINTS;
94	        }
95	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
96	            points += NO_NAMESAKE_POINTS;
97	        }
98	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_SIZE) {
99	            points += LARGE_HOUSEHOLD_POINTS;
100	        }
101	        if (tenureDays(owner) > TENURE_POINTS_DAYS) {
102	            points += TENURE_POINTS;
103	        }
104	        return points;
105	    }
106	
107	    /**
108	     * Maps an owner's membership points to a numeric membership level: level 1 for 0-1 points, level 2 for
109	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
110	     *
111	     * @param owner the owner whose level is being computed
112	     * @return the membership level (between 1 and 4 inclusive)
113	     */
114	    protected Integer membershipLevel(Owner owner) {
115	        int points = membershipPoints(owner);
116	        if (points >= 6) {
117	            return 4;
118	        }
119	        if (points >= 4) {
120	            return 3;
121	        }
122	        if (points >= 2) {
123	            return 2;
124	        }
125	        return 1;
126	    }
127	
128	    /**
129	     * Computes an owner's tenure in days: the number of days between {@code registrationDate} and today. A
130	     * newly created owner (registered today) has zero tenure. Owners with no {@code registrationDate}, or a
131	     * registration date in the future, are treated as having zero tenure.
132	     *
133	     * @param owner the owner whose tenure is being computed
134	     * @return the owner's tenure in days, never negative
135	     */
136	    protected long tenureDays(Owner owner) {
137	        LocalDate registrationDate = owner.getRegistrationDate();
138	        if (registrationDate == null) {
139	            return 0;
140	        }
141	        long days = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
142	        return Math.max(days, 0);
143	    }
144	
145	    /**
146	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits contained in
147	     * the owner's {@code customerCode}. Non-digit characters (such as the letters and dashes in the code) are
148	     * skipped; the rightmost digit is doubled and every second digit thereafter, digits exceeding 9 after
149	     * doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
150	     *
151	     * @param owner the owner whose check digit is being computed
152	     * @return the Luhn check digit (between 0 and 9 inclusive) over the customer code's digits
153	     */
154	    protected Integer checkDigit(Owner owner) {
155	        String code = owner.getCustomerCode() == null ? "" : owner.getCustomerCode();
156	        int sum = 0;
157	        boolean dbl = true;
158	        for (int i = code.length() - 1; i >= 0; i--) {
159	            char c = code.charAt(i);
160	            if (c < '0' || c > '9') {
161	                continue;
162	            }
163	            int d = c - '0';
164	            if (dbl) {
165	                d *= 2;
166	                if (d > 9) {
167	                    d -= 9;
168	                }
169	            }
170	            sum += d;
171	            dbl = !dbl;
172	        }
173	        return (10 - (sum % 10)) % 10;
174	    }
175	
176	    /**
177	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
178	     * present, otherwise {@code 'PHONE'}.
179	     *
180	     * @param owner the owner whose contact preference is being computed
181	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
182	     */
183	    protected String contactPreference(Owner owner) {
184	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
185	    }
186	
187	    /**
188	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
189	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
190	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
191	     * {@code birthDate}, so the field is simply absent for owners created without one.
192	     *
193	     * @param owner the owner whose age band is being derived
194	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
195	     */
196	    protected String ageBand(Owner owner) {
197	        if (owner.getBirthDate() == null) {
198	            return null;
199	        }
200	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
201	        int years = Period.between(owner.getBirthDate(), reference).getYears();
202	        if (years < 18) {
203	            return "MINOR";
204	        }
205	        if (years < 65) {
206	            return "ADULT";
207	        }
208	        return "SENIOR";
209	    }
210	
211	    /**
212	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
213	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
214	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'}). This is the single key used for duplicate detection,
215	     * so the value returned here matches the one the create endpoint compares.
216	     *
217	     * @param owner the owner whose identity key is being derived
218	     * @return the owner's identity key
219	     */
220	    protected String identityKey(Owner owner) {
221	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
222	        String email = owner.getEmail() == null ? "" : owner.getEmail();
223	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
224	        return telephone + "|" + email + "|" + householdId;
225	    }
226	
227	    /**
228	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
229	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
230	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
231	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
232	     * <p>
233	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
234	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
235	     *
236	     * @param owner the owner whose telephone is being formatted
237	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
238	     */
239	    protected String telephoneDisplay(Owner owner) {
240	        String telephone = owner.getTelephone();
241	        if (telephone == null || !telephone.startsWith("+")) {
242	            return telephone;
243	        }
244	        String digits = telephone.substring(1);
245	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
246	        if (digits.length() <= countryCodeLength) {
247	            return telephone;
248	        }
249	        String countryCode = digits.substring(0, countryCodeLength);
250	        String national = digits.substring(countryCodeLength);
251	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
252	        for (int i = 0; i < national.length(); i++) {
253	            if (i % 3 == 0) {
254	                grouped.append(' ');
255	            }
256	            grouped.append(national.charAt(i));
257	        }
258	        return grouped.toString();
259	    }
260	
261	    /**
262	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
263	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
264	     * title was given.
265	     *
266	     * @param owner the owner whose salutation is being composed
267	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
268	     */
269	    protected String salutation(Owner owner) {
270	        String title = owner.getTitle();
271	        if (title == null || title.isBlank()) {
272	            return owner.getLastName();
273	        }
274	        return title + " " + owner.getLastName();
275	    }
276	
277	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
278	        OwnerPageDto ownerPageDto = new OwnerPageDto();
279	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
280	        ownerPageDto.setPage(ownerPage.getNumber());
281	        ownerPageDto.setSize(ownerPage.getSize());
282	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
283	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
284	        return ownerPageDto;
285	    }
286	}
